(5667049, 824615, 110294, '<td valign="top">Beautiful Colors and DOF</td>', 'Beautiful Colors and DOF', '2009-09-30 07:31:51.000000', NULL, 1),
(5667051, 823837, 30982, '<td valign="top">Kinda meets the challenge but "straight" is probably not the first thing people would say if you asked them what this photo was about.  Pretty good exposure for a situation with light and shadow; could use a bit of sharpening to really bring it out well at this small size.</td>', 'Kinda meets the challenge but "straight" is probably not the first thing people would say if you asked them what this photo was about.  Pretty good exposure for a situation with light and shadow; could use a bit of sharpening to really bring it out well at this small size.', '2009-09-30 07:33:07.000000', NULL, 1),
