(5667146, 824575, 30982, '<td valign="top">Interesting perspective!  The vibrance is VERY vibrant, perhaps a bit much.</td>', 'Interesting perspective!  The vibrance is VERY vibrant, perhaps a bit much.', '2009-09-30 08:39:42.000000', NULL, 1),
