(5672709, 824612, 5746, '<td valign="top">Very nice composition. I have no idea what is it, but I like it.</td>', 'Very nice composition. I have no idea what is it, but I like it.', '2009-10-03 09:51:12.000000', NULL, 1),
(5672712, 824588, 5746, '<td valign="top">You''ve got good eye for detail. I like it a lot :)</td>', 'You''ve got good eye for detail. I like it a lot :)', '2009-10-03 09:51:43.000000', NULL, 1),
(5672716, 823783, 5746, '<td valign="top">Nice colours and composition which gives a sense of depth. It''s tilted a bit to the right.</td>', 'Nice colours and composition which gives a sense of depth. It''s tilted a bit to the right.', '2009-10-03 09:53:14.000000', NULL, 1),
(5672720, 823735, 5746, '<td valign="top">Nice moody composition. I like the foggy skyline.</td>', 'Nice moody composition. I like the foggy skyline.', '2009-10-03 09:54:33.000000', NULL, 1),
(5672721, 824257, 5746, '<td valign="top">Lovely lighting and detail.</td>', 'Lovely lighting and detail.', '2009-10-03 09:54:48.000000', NULL, 1),
(5672725, 824480, 5746, '<td valign="top">Very, very nice. Crisp and juicy. Looks a bit like a guitar riff. Good luck.</td>', 'Very, very nice. Crisp and juicy. Looks a bit like a guitar riff. Good luck.', '2009-10-03 09:57:33.000000', NULL, 1),
(5672729, 824547, 5746, '<td valign="top">Wow. Great quality. I love the sharpness and strong contrast. Good luck!</td>', 'Wow. Great quality. I love the sharpness and strong contrast. Good luck!', '2009-10-03 09:59:08.000000', NULL, 1),
(5672732, 824566, 5746, '<td valign="top">What a nice sky. The detail in water is amazing. Very moody. Good luck!</td>', 'What a nice sky. The detail in water is amazing. Very moody. Good luck!', '2009-10-03 09:59:43.000000', NULL, 1),
(5672734, 824575, 5746, '<td valign="top">A bit over-saturated for my taste. Looks almost fake.</td>', 'A bit over-saturated for my taste. Looks almost fake.', '2009-10-03 10:00:46.000000', NULL, 1),
(5672736, 823757, 5746, '<td valign="top">Nice concept. The water looks like steel strains.</td>', 'Nice concept. The water looks like steel strains.', '2009-10-03 10:01:19.000000', NULL, 1),
(5672738, 824079, 5746, '<td valign="top">Nice detail. Looks like 50th advert :)</td>', 'Nice detail. Looks like 50th advert :)', '2009-10-03 10:02:09.000000', NULL, 1),
(5672742, 823785, 5746, '<td valign="top">Nice simple composition. Good luck.</td>', 'Nice simple composition. Good luck.', '2009-10-03 10:03:44.000000', NULL, 1),
(5672759, 824714, 5746, '<td valign="top">Great idea and composition. Bumping up to 9.</td>', 'Great idea and composition. Bumping up to 9.', '2009-10-03 10:11:07.000000', NULL, 1),
(5672761, 823505, 5746, '<td valign="top">Excellent. 10.</td>', 'Excellent. 10.', '2009-10-03 10:11:30.000000', NULL, 1),
(5673298, 823349, 19178, '<td valign="top">Is there something vaguely disturbing about this image?  It is, however, my favorite in this challenge!</td>', 'Is there something vaguely disturbing about this image?  It is, however, my favorite in this challenge!', '2009-10-03 17:00:59.000000', NULL, 1),
(5673301, 824411, 19178, '<td valign="top">One of my favorites.  A tiny bit more shadow detail in the left bridge would improve it even more.</td>', 'One of my favorites.  A tiny bit more shadow detail in the left bridge would improve it even more.', '2009-10-03 17:02:22.000000', NULL, 1),
(5673303, 824708, 19178, '<td valign="top">I get the idea of "Straight, no chaser," but this image seems a bit tipsy due to a lack of focus!</td>', 'I get the idea of "Straight, no chaser," but this image seems a bit tipsy due to a lack of focus!', '2009-10-03 17:04:19.000000', NULL, 1),
(5673309, 824499, 19178, '<td valign="top">This seems a bit nondescript.  Take a look at:<br/> <br/><a href="//fineartamerica.com/featured/aspens-adam-romanowicz.html" rel="nofollow" target="_blank">Aspens</a></td>', 'This seems a bit nondescript.  Take a look at: Aspens', '2009-10-03 17:07:16.000000', NULL, 1),
(5673384, 823938, 106349, '<td valign="top">Great affects.</td>', 'Great affects.', '2009-10-03 18:30:26.000000', NULL, 1),
(5673388, 824608, 106349, '<td valign="top">When I scroll up &amp; down it makes me dizzy. <br/> <br/>Nice angle. :o)</td>', 'When I scroll up & down it makes me dizzy.  Nice angle. :o)', '2009-10-03 18:31:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5673398, 823731, 106349, '<td valign="top">Like the composition on this one. A lot of people entered something similar to this but yours sticks out as different. Good job.</td>', 'Like the composition on this one. A lot of people entered something similar to this but yours sticks out as different. Good job.', '2009-10-03 18:35:23.000000', NULL, 1),
(5673399, 824613, 106349, '<td valign="top">Could be me... but it looks a little crooked.</td>', 'Could be me... but it looks a little crooked.', '2009-10-03 18:36:18.000000', NULL, 1),
(5673584, 824449, 15511, '<td valign="top">It would have been interesting to see some of the details in the shadows.</td>', 'It would have been interesting to see some of the details in the shadows.', '2009-10-03 20:59:35.000000', NULL, 1),
(5673587, 824441, 15511, '<td valign="top">Image would have more impact if all areas were in focus.</td>', 'Image would have more impact if all areas were in focus.', '2009-10-03 21:03:01.000000', NULL, 1),
(5673669, 824693, 64446, '<td valign="top">Nice image, but don''t see the connection with the challenge.</td>', 'Nice image, but don''t see the connection with the challenge.', '2009-10-03 22:47:57.000000', NULL, 1),
(5673673, 824608, 64446, '<td valign="top">Interesting patterns, but the many round lines compromise the description of the challenge.</td>', 'Interesting patterns, but the many round lines compromise the description of the challenge.', '2009-10-03 22:51:49.000000', NULL, 1),
(5673702, 823837, 64446, '<td valign="top">That''s a little to pushy to meet the challenge. As for the image per see, the focus seems a bit soft (which is not necessary bad) and the brightness is high - the image appears washed out...</td>', 'That''s a little to pushy to meet the challenge. As for the image per see, the focus seems a bit soft (which is not necessary bad) and the brightness is high - the image appears washed out...', '2009-10-03 23:22:17.000000', NULL, 1),
(5673703, 823468, 64446, '<td valign="top">Though the subject matter is not not attractive, it does fit the challenge. Having said that I see many down sides with the image. The focus is soft and the lighting is flat. There seems to be no relation between the people on the image with the "Dance" theme. It would be more effective not having nobody in the frame at all (it would be more boring too...). The persons are cropped out - with exceptions, cropping or cutting people/limbs is not a good thing to do.</td>', 'Though the subject matter is not not attractive, it does fit the challenge. Having said that I see many down sides with the image. The focus is soft and the lighting is flat. There seems to be no relation between the people on the image with the "Dance" theme. It would be more effective not having nobody in the frame at all (it would be more boring too...). The persons are cropped out - with exceptions, cropping or cutting people/limbs is not a good thing to do.', '2009-10-03 23:22:20.000000', NULL, 1),
(5673704, 824708, 64446, '<td valign="top">I can`t see any relation of this image with the challenge definition.</td>', 'I can`t see any relation of this image with the challenge definition.', '2009-10-03 23:22:22.000000', NULL, 1),
(5673708, 824288, 64446, '<td valign="top">Is this the BCE Place? Anyway, as the challenge goes I''m afraid you didn''t abide 100% on it as there are several non-straight lines there. I think you''ll get many DNMCs.<br/>I like the image per se. The focus is sharp. It provides interesting patterns and I like what appear to be some reflections on the glass. I don`t care for the thicker border though -  it competes with the thinner white lines of the structure.</td>', 'Is this the BCE Place? Anyway, as the challenge goes I''m afraid you didn''t abide 100% on it as there are several non-straight lines there. I think you''ll get many DNMCs.I like the image per se. The focus is sharp. It provides interesting patterns and I like what appear to be some reflections on the glass. I don`t care for the thicker border though -  it competes with the thinner white lines of the structure.', '2009-10-03 23:27:37.000000', NULL, 1),
(5673713, 824697, 64446, '<td valign="top">Nice view and an story going on here, but there is a big issue of not meeting the challenge: the courtyard has all but straight lines there. As for the bars, the seem skewed.</td>', 'Nice view and an story going on here, but there is a big issue of not meeting the challenge: the courtyard has all but straight lines there. As for the bars, the seem skewed.', '2009-10-03 23:33:04.000000', NULL, 1),
(5673718, 824633, 64446, '<td valign="top">No doubt it meets the challenge. The patterns and color nuances are OK, but the light is too harsh and the focus is not good. Also, the longer side of the image is only 400 pixels, while you could have used 640, which would give more details to the viewer.</td>', 'No doubt it meets the challenge. The patterns and color nuances are OK, but the light is too harsh and the focus is not good. Also, the longer side of the image is only 400 pixels, while you could have used 640, which would give more details to the viewer.', '2009-10-03 23:37:22.000000', NULL, 1),
(5673726, 824361, 64446, '<td valign="top">Nice perspective and the interesting having a Braille tower depicted.<br/>The main building, however, seems to have round facade, which might hurt you with DNMC.</td>', 'Nice perspective and the interesting having a Braille tower depicted.The main building, however, seems to have round facade, which might hurt you with DNMC.', '2009-10-03 23:40:21.000000', NULL, 1),
(5673739, 824408, 42495, '<td valign="top">Good B&amp;W treatment; I would use the entire 640 pixels alloted and try to avoid putting the center beam in the middle.</td>', 'Good B&W treatment; I would use the entire 640 pixels alloted and try to avoid putting the center beam in the middle.', '2009-10-03 23:46:49.000000', NULL, 1),
(5673742, 824369, 42495, '<td valign="top">Really cute portrait, but to me it''s more of a portrait than demonstrating "straight".</td>', 'Really cute portrait, but to me it''s more of a portrait than demonstrating "straight".', '2009-10-03 23:48:16.000000', NULL, 1),
(5673746, 824213, 42495, '<td valign="top">Love the blues and perspective.</td>', 'Love the blues and perspective.', '2009-10-03 23:49:36.000000', NULL, 1),
(5673753, 823468, 42495, '<td valign="top">I''m guessing the picture is what you consider straight, but I''m seeing a lot of other things in your photo to draw my eye.</td>', 'I''m guessing the picture is what you consider straight, but I''m seeing a lot of other things in your photo to draw my eye.', '2009-10-03 23:51:47.000000', NULL, 1),
(5673762, 824480, 64446, '<td valign="top">Nice lines, but they don''t seem to be that straight, do they?</td>', 'Nice lines, but they don''t seem to be that straight, do they?', '2009-10-03 23:55:20.000000', NULL, 1),
(5673765, 824704, 42495, '<td valign="top">Yep, perfect title for this. Cool shot.</td>', 'Yep, perfect title for this. Cool shot.', '2009-10-03 23:55:58.000000', NULL, 1),
(5673767, 823534, 64446, '<td valign="top">Humm, that bowl seems to show off very round lines... Interesting tilt and the negative effect of the split image, though.</td>', 'Humm, that bowl seems to show off very round lines... Interesting tilt and the negative effect of the split image, though.', '2009-10-03 23:58:02.000000', NULL, 1),
(5673768, 824499, 64446, '<td valign="top">Small image, details compromised.</td>', 'Small image, details compromised.', '2009-10-03 23:58:33.000000', NULL, 1),
(5673769, 824464, 42495, '<td valign="top">You certainly met the challenge, but perhaps putting the corner on a third or looking down the side of the building would help the composition.</td>', 'You certainly met the challenge, but perhaps putting the corner on a third or looking down the side of the building would help the composition.', '2009-10-03 23:58:50.000000', NULL, 1),
(5673772, 824591, 42495, '<td valign="top">One of the more interesting photos of the challenge. I would probably crop off the top dark area to keep the focus on the porcelain, but that''s just my opinion.</td>', 'One of the more interesting photos of the challenge. I would probably crop off the top dark area to keep the focus on the porcelain, but that''s just my opinion.', '2009-10-04 00:00:58.000000', NULL, 1),
(5673773, 824355, 64446, '<td valign="top">Nice perspective, though the focus or DOF is too shallow.</td>', 'Nice perspective, though the focus or DOF is too shallow.', '2009-10-04 00:00:59.000000', NULL, 1),
(5673774, 824625, 64446, '<td valign="top">Nice perspective. It would help if it was not that dark...</td>', 'Nice perspective. It would help if it was not that dark...', '2009-10-04 00:02:16.000000', NULL, 1),
(5673775, 824510, 64446, '<td valign="top">Great action image, but a little too pushy to meet the challenge...</td>', 'Great action image, but a little too pushy to meet the challenge...', '2009-10-04 00:02:20.000000', NULL, 1),
(5673776, 824575, 64446, '<td valign="top">Way too saturated colours!</td>', 'Way too saturated colours!', '2009-10-04 00:02:23.000000', NULL, 1),
(5673777, 823327, 42495, '<td valign="top">I liked this until I saw the shadow.  Now I like it even better.  Well done.</td>', 'I liked this until I saw the shadow.  Now I like it even better.  Well done.', '2009-10-04 00:02:33.000000', NULL, 1),
(5673778, 824411, 64446, '<td valign="top">Nice perspective. Too bad that reflection though...</td>', 'Nice perspective. Too bad that reflection though...', '2009-10-04 00:03:14.000000', NULL, 1),
(5673779, 824614, 42495, '<td valign="top">Nice.  Just enough of the girl shows to draw me in.</td>', 'Nice.  Just enough of the girl shows to draw me in.', '2009-10-04 00:04:20.000000', NULL, 1),
(5673780, 824663, 64446, '<td valign="top">Though all lines are stratight, the termination of the "whatever those white sticks are" form a non-straight line/shape in the image. Not sure how the DNMC folks will take it.<br/>I would like to see more contrast, specially on the sky, and not see that line on top right (too bad it''s Basic and you couldn''t clone it away).</td>', 'Though all lines are stratight, the termination of the "whatever those white sticks are" form a non-straight line/shape in the image. Not sure how the DNMC folks will take it.I would like to see more contrast, specially on the sky, and not see that line on top right (too bad it''s Basic and you couldn''t clone it away).', '2009-10-04 00:09:10.000000', NULL, 1),
(5673782, 824385, 42495, '<td valign="top">Good take on a simple subject.  I probably wold have cropped a tad off the right to get the main vertical rain on a third.</td>', 'Good take on a simple subject.  I probably wold have cropped a tad off the right to get the main vertical rain on a third.', '2009-10-04 00:09:34.000000', NULL, 1),
(5673784, 824415, 64446, '<td valign="top">The little round forms in the window likely with grant you many DNMCs. It didn''t bother me much. I don''t care for the border though.</td>', 'The little round forms in the window likely with grant you many DNMCs. It didn''t bother me much. I don''t care for the border though.', '2009-10-04 00:11:45.000000', NULL, 1),
(5673868, 824656, 83313, '<td valign="top">Just comes off to me as a snapshot, though I do think a few image adjustments could bump it up a half notch. Some levels, curves, saturation, &amp; contrast would do a lot.</td>', 'Just comes off to me as a snapshot, though I do think a few image adjustments could bump it up a half notch. Some levels, curves, saturation, & contrast would do a lot.', '2009-10-04 02:04:30.000000', NULL, 1),
(5673869, 824368, 83313, '<td valign="top">Mostly a good vote.</td>', 'Mostly a good vote.', '2009-10-04 02:05:37.000000', NULL, 1),
(5673871, 824625, 83313, '<td valign="top">Would probably be a good one if it wasn''t so dark and hard to make out.</td>', 'Would probably be a good one if it wasn''t so dark and hard to make out.', '2009-10-04 02:10:43.000000', NULL, 1),
(5673878, 824355, 83313, '<td valign="top">Kind of a blah shot of an ordinary item.  However, I do see some potential in this shot. It''s a genre that I think of as "semi-abstract". I popped it into paintshop pro to see and I found that some simple adjustments (levels, curves, saturation &amp; contrast) really brought out some nice detail and colors. Good macro work with the camera that is being limited by the post processing. I''ll be interested in checking back on this one after the challenge.</td>', 'Kind of a blah shot of an ordinary item.  However, I do see some potential in this shot. It''s a genre that I think of as "semi-abstract". I popped it into paintshop pro to see and I found that some simple adjustments (levels, curves, saturation & contrast) really brought out some nice detail and colors. Good macro work with the camera that is being limited by the post processing. I''ll be interested in checking back on this one after the challenge.', '2009-10-04 02:18:48.000000', NULL, 1),
(5673965, 824681, 5746, '<td valign="top">B&amp;W was an excellent choice :) Interesting composition, great detail. I love architecture shots. Bumping up to 8.</td>', 'B&W was an excellent choice :) Interesting composition, great detail. I love architecture shots. Bumping up to 8.', '2009-10-04 06:02:36.000000', NULL, 1),
(5673966, 824240, 5746, '<td valign="top">Falling star is a remarkable add on in this picture. I love the detail here and the mirror-like reflections. Nice composition. Due to the extremely calm water, I think 100% symmetry would enhance the straight lines more. Good luck :) Bumping up to 8.</td>', 'Falling star is a remarkable add on in this picture. I love the detail here and the mirror-like reflections. Nice composition. Due to the extremely calm water, I think 100% symmetry would enhance the straight lines more. Good luck :) Bumping up to 8.', '2009-10-04 06:02:46.000000', NULL, 1),
(5673989, 823882, 32011, '<td valign="top">This is one of two top scoring photos following my voting phase, and now looking at it for comments, all I can really say is that this is really something I could see on my wall.  Composition and contrast is fantastic... great job.</td>', 'This is one of two top scoring photos following my voting phase, and now looking at it for comments, all I can really say is that this is really something I could see on my wall.  Composition and contrast is fantastic... great job.', '2009-10-04 07:16:28.000000', NULL, 1),
(5673992, 824681, 32011, '<td valign="top">Best architectural photo in this challenge, and one of two top scoring images from my voting phase.  Contrast is brilliant, and the composition is spot on.  Well done.</td>', 'Best architectural photo in this challenge, and one of two top scoring images from my voting phase.  Contrast is brilliant, and the composition is spot on.  Well done.', '2009-10-04 07:18:28.000000', NULL, 1),
(5673993, 824445, 32011, '<td valign="top">This is a favourite for a posthumous... without a doubt... and is one of my favourites in the challenge.  Beautiful abstract, and a breathe of fresh air in this challenge.  Thank you for daring to be different... hope it does as well as I think it deserves to.</td>', 'This is a favourite for a posthumous... without a doubt... and is one of my favourites in the challenge.  Beautiful abstract, and a breathe of fresh air in this challenge.  Thank you for daring to be different... hope it does as well as I think it deserves to.', '2009-10-04 07:20:38.000000', NULL, 1),
(5673994, 824302, 32011, '<td valign="top">I score this image quite high in my voting phase, and now I''m commenting, I think the simplicity and the colour really appealed to me.  I love the colour gradient, and the detail in the wood... and the composition is excellent.</td>', 'I score this image quite high in my voting phase, and now I''m commenting, I think the simplicity and the colour really appealed to me.  I love the colour gradient, and the detail in the wood... and the composition is excellent.', '2009-10-04 07:23:59.000000', NULL, 1),
(5673998, 823258, 32011, '<td valign="top">This is a fantastic photo.  I really love the balance of colours and minimalism,  The ONE thing that I would have changed was the white thing at the top, though, that''s easier said than done give the basic editing restriction, and the need to keep the left of the image to get the composition impact you''ve nailed.  Wonderful photo and I hope it does well.</td>', 'This is a fantastic photo.  I really love the balance of colours and minimalism,  The ONE thing that I would have changed was the white thing at the top, though, that''s easier said than done give the basic editing restriction, and the need to keep the left of the image to get the composition impact you''ve nailed.  Wonderful photo and I hope it does well.', '2009-10-04 07:27:31.000000', NULL, 1),
(5674006, 824591, 32011, '<td valign="top">I only gave this a 7 when I was voting, but I''m thinking it''s actually one of my favourite images, and might deserve a bump... okay... what''s good?... colours are superb, absolutely brilliant, the composition is great, though I think you could have lost some of the black at the top (I think).  I also love that this is different... you have GREAT vision.  What''s bad?  Other than the black at the top, I can''t think of anything... so... with all that said, how can I not bump it up a point or two... okay... a NINE, which will make it the highest score I''ve given in this challenge (leapfrog the 2 eights).  Well done.</td>', 'I only gave this a 7 when I was voting, but I''m thinking it''s actually one of my favourite images, and might deserve a bump... okay... what''s good?... colours are superb, absolutely brilliant, the composition is great, though I think you could have lost some of the black at the top (I think).  I also love that this is different... you have GREAT vision.  What''s bad?  Other than the black at the top, I can''t think of anything... so... with all that said, how can I not bump it up a point or two... okay... a NINE, which will make it the highest score I''ve given in this challenge (leapfrog the 2 eights).  Well done.', '2009-10-04 07:34:02.000000', NULL, 1),
(5674008, 824729, 32011, '<td valign="top">I scored this fairly high when voting... commenting now, how could you have got higher from me?  I think this lacks a story... a point of focus... a chess piece somewhere perhaps.  I don''t know.</td>', 'I scored this fairly high when voting... commenting now, how could you have got higher from me?  I think this lacks a story... a point of focus... a chess piece somewhere perhaps.  I don''t know.', '2009-10-04 07:37:46.000000', NULL, 1),
(5674010, 824588, 32011, '<td valign="top">This image had me conflicted when voting... gave it a reasonable 7 back then, but now, I''m commenting, and I''m looking at it and think I WAY too hard on it/you.  Composition is wonderful, and the contract is great.  I reckon its a serious chance for a posthumous...  okay... upgrading it up to an 8... might be back to bump it to a 9, as I''m still feeling an 8 might be a tad harsh... stuff it... save myself the effort of coming back... a 9 from me.  Well done!</td>', 'This image had me conflicted when voting... gave it a reasonable 7 back then, but now, I''m commenting, and I''m looking at it and think I WAY too hard on it/you.  Composition is wonderful, and the contract is great.  I reckon its a serious chance for a posthumous...  okay... upgrading it up to an 8... might be back to bump it to a 9, as I''m still feeling an 8 might be a tad harsh... stuff it... save myself the effort of coming back... a 9 from me.  Well done!', '2009-10-04 07:45:59.000000', NULL, 1),
(5674030, 824611, 102994, '<td valign="top">nice effect!</td>', 'nice effect!', '2009-10-04 08:13:28.000000', NULL, 1),
(5674031, 824625, 102994, '<td valign="top">I think it would of been better lightened up a bit, its just too dark</td>', 'I think it would of been better lightened up a bit, its just too dark', '2009-10-04 08:17:02.000000', NULL, 1),
(5674119, 823882, 64086, '<td valign="top">nice tones and composition</td>', 'nice tones and composition', '2009-10-04 09:40:28.000000', NULL, 1),
(5674436, 824614, 17279, '<td valign="top">A compelling image.  I don''t think you needed to have the hands at the top of the photo.  Also, I wonder if there is some way to really emphasize the face and somewhat de-emphasize the fence in order to draw the viewer''s attention right to the child.</td>', 'A compelling image.  I don''t think you needed to have the hands at the top of the photo.  Also, I wonder if there is some way to really emphasize the face and somewhat de-emphasize the fence in order to draw the viewer''s attention right to the child.', '2009-10-04 15:00:17.000000', NULL, 1),
(5674437, 824480, 17279, '<td valign="top">Nicely done.  I would have liked to see the white trails of the onco,ming traffic as well to offset the abundance of red.  Not sure if that was possible with the location though.</td>', 'Nicely done.  I would have liked to see the white trails of the onco,ming traffic as well to offset the abundance of red.  Not sure if that was possible with the location though.', '2009-10-04 15:01:25.000000', NULL, 1),
(5674439, 824302, 17279, '<td valign="top">An interesting image.  Simple and clean.  Interesting how the gradation of color in the sky works opposite to the gradation of color in the pole.</td>', 'An interesting image.  Simple and clean.  Interesting how the gradation of color in the sky works opposite to the gradation of color in the pole.', '2009-10-04 15:02:32.000000', NULL, 1),
(5674440, 824674, 17279, '<td valign="top">Not sure what this is, but I like it.  I think cropping out a good chunk of the negative space at the bottom might enhance this photo some.</td>', 'Not sure what this is, but I like it.  I think cropping out a good chunk of the negative space at the bottom might enhance this photo some.', '2009-10-04 15:03:19.000000', NULL, 1),
(5674441, 823937, 17279, '<td valign="top">Nice image.  I would have liked to see more of the shutter on the left and a bit more of the window frame as well. The blues also seem a bit saturated on my monitor.</td>', 'Nice image.  I would have liked to see more of the shutter on the left and a bit more of the window frame as well. The blues also seem a bit saturated on my monitor.', '2009-10-04 15:04:44.000000', NULL, 1),
(5674445, 823837, 17279, '<td valign="top">I don''t quite see how this conveys the challenge topic absent the title.  I think it''s a bit of a stretch, but an interesting image nonetheless.  Might it look better as a black and white?</td>', 'I don''t quite see how this conveys the challenge topic absent the title.  I think it''s a bit of a stretch, but an interesting image nonetheless.  Might it look better as a black and white?', '2009-10-04 15:09:19.000000', NULL, 1),
(5674447, 824534, 17279, '<td valign="top">There seems to be too much in this image other than the fence, which takes away from the main subject.  Perhaps a tighter crop?</td>', 'There seems to be too much in this image other than the fence, which takes away from the main subject.  Perhaps a tighter crop?', '2009-10-04 15:10:16.000000', NULL, 1),
(5674448, 824657, 17279, '<td valign="top">Honestly, I am not sure what this is, and the patterns on the subject don''t really convey "straight" to me... it''s more of a diamond pattern.</td>', 'Honestly, I am not sure what this is, and the patterns on the subject don''t really convey "straight" to me... it''s more of a diamond pattern.', '2009-10-04 15:11:10.000000', NULL, 1),
(5674449, 824369, 17279, '<td valign="top">I think by having the straight lines (fence) out of focus, you shift the significance of the image to the face and you lose the connection to the challenge theme.</td>', 'I think by having the straight lines (fence) out of focus, you shift the significance of the image to the face and you lose the connection to the challenge theme.', '2009-10-04 15:12:15.000000', NULL, 1),
(5674450, 823505, 17279, '<td valign="top">A beautiful image, no question.  great colors and detail.  I am not sure it really conveys the challenge topic however, as there are so many significant patterns and colors that they de-emphasize any focus on the lines specifically.</td>', 'A beautiful image, no question.  great colors and detail.  I am not sure it really conveys the challenge topic however, as there are so many significant patterns and colors that they de-emphasize any focus on the lines specifically.', '2009-10-04 15:13:38.000000', NULL, 1),
(5674451, 823909, 17279, '<td valign="top">I assume the title should be STRINGS of solitude?  I think this coule be a much stronger image if you had the strings at more of an angle diagonally, losing some of the empty space around the image and drawing more focus to the strings.</td>', 'I assume the title should be STRINGS of solitude?  I think this coule be a much stronger image if you had the strings at more of an angle diagonally, losing some of the empty space around the image and drawing more focus to the strings.', '2009-10-04 15:15:10.000000', NULL, 1),
(5674452, 824408, 17279, '<td valign="top">Interesting image with great lines.  I like the contrast and black and white treatment.  However, I think a different framing would make this a stronger image.  The pole essentially running down the center (and not even straight) really detracts from the image.</td>', 'Interesting image with great lines.  I like the contrast and black and white treatment.  However, I think a different framing would make this a stronger image.  The pole essentially running down the center (and not even straight) really detracts from the image.', '2009-10-04 15:16:24.000000', NULL, 1),
(5674454, 823468, 17279, '<td valign="top">Hmmm... not sure what to make of this.  Certainly, there are straight lines in this, but it appears that the focus of the image is merely the lines in the artwork.  I think this might be more effective without the people and somehow using the straight lines of the wall/floor (maybe even the corner wall of the room) and the art frame as significant points of interest.</td>', 'Hmmm... not sure what to make of this.  Certainly, there are straight lines in this, but it appears that the focus of the image is merely the lines in the artwork.  I think this might be more effective without the people and somehow using the straight lines of the wall/floor (maybe even the corner wall of the room) and the art frame as significant points of interest.', '2009-10-04 15:19:05.000000', NULL, 1),
(5674455, 824697, 17279, '<td valign="top">It''s an interesting and worthwhile concept.  I don''t know if it would have been possible, but the angle at which this was shot could be different so as to better position the points of interest in the background at key points in the spaces between the bars.</td>', 'It''s an interesting and worthwhile concept.  I don''t know if it would have been possible, but the angle at which this was shot could be different so as to better position the points of interest in the background at key points in the spaces between the bars.', '2009-10-04 15:20:38.000000', NULL, 1),
(5674458, 824708, 17279, '<td valign="top">This image is a bit too dark and seems to have too shallow DOF for my taste.  I really don''t get a strong sense of the challenge theme from this.</td>', 'This image is a bit too dark and seems to have too shallow DOF for my taste.  I really don''t get a strong sense of the challenge theme from this.', '2009-10-04 15:21:57.000000', NULL, 1),
(5674460, 824228, 17279, '<td valign="top">While there are straight lines in this image. the bits of red (spray paint?) are quite a distraction and really draw the eyes away from the pattern of lines.</td>', 'While there are straight lines in this image. the bits of red (spray paint?) are quite a distraction and really draw the eyes away from the pattern of lines.', '2009-10-04 15:24:47.000000', NULL, 1),
(5674463, 824585, 17279, '<td valign="top">Interesting title given the challenge topic of "straight"  Nice colors and concept.  Good effort.</td>', 'Interesting title given the challenge topic of "straight"  Nice colors and concept.  Good effort.', '2009-10-04 15:26:33.000000', NULL, 1),
(5674474, 824073, 17279, '<td valign="top">Nice colors and an interesting take on the topic.  I''m not sure the composition works for me very well.  Perhaps more of an angle (landscape orientation?), with the wires moving off diagonally.</td>', 'Nice colors and an interesting take on the topic.  I''m not sure the composition works for me very well.  Perhaps more of an angle (landscape orientation?), with the wires moving off diagonally.', '2009-10-04 15:32:55.000000', NULL, 1),
(5674476, 824641, 17279, '<td valign="top">Nice take on the challenge and I like the black and white.  There is a bit too much though in this image competing for attention (too many different sets of lines running in different directions but not creating some type of pattern or flow).</td>', 'Nice take on the challenge and I like the black and white.  There is a bit too much though in this image competing for attention (too many different sets of lines running in different directions but not creating some type of pattern or flow).', '2009-10-04 15:35:11.000000', NULL, 1),
(5674477, 823896, 17279, '<td valign="top">Nice image and good composition.  I would like to see a bit more contrast between the supports and the darker portions of the image.  I really like the negative space in the upper left of the image but not sure I can say the same about the bottom of the image.</td>', 'Nice image and good composition.  I would like to see a bit more contrast between the supports and the darker portions of the image.  I really like the negative space in the upper left of the image but not sure I can say the same about the bottom of the image.', '2009-10-04 15:35:14.000000', NULL, 1),
(5674478, 824693, 17279, '<td valign="top">Beautiful image and excellent colors.  A bit tenuous on the connection to the challenge theme though.</td>', 'Beautiful image and excellent colors.  A bit tenuous on the connection to the challenge theme though.', '2009-10-04 15:35:17.000000', NULL, 1),
(5674517, 824664, 83313, '<td valign="top">Tons of visible JPEG compression, though I am not sure how, as your filesize is 141k, which should be sufficient for a nice smooth image. It is possible that you could have been saving your working copy as a JPG. Repeated opening and resaving of a JPG could cause this. Always save working copies as an uncompressed format, such as TIF or the native file format for you photo editing application. (Such as PSD for Photoshop or PSPIMAGE for PaintShop Pro)</td>', 'Tons of visible JPEG compression, though I am not sure how, as your filesize is 141k, which should be sufficient for a nice smooth image. It is possible that you could have been saving your working copy as a JPG. Repeated opening and resaving of a JPG could cause this. Always save working copies as an uncompressed format, such as TIF or the native file format for you photo editing application. (Such as PSD for Photoshop or PSPIMAGE for PaintShop Pro)', '2009-10-04 16:36:36.000000', NULL, 1),
(5674518, 824302, 83313, '<td valign="top">A pretty good and well done shot of a normally boring an uninteresting subject. The fade of the sky is really nice and smooth.</td>', 'A pretty good and well done shot of a normally boring an uninteresting subject. The fade of the sky is really nice and smooth.', '2009-10-04 16:38:21.000000', NULL, 1),
(5674520, 823882, 83313, '<td valign="top">I like seeing interesting photos of ordinary subjects. Shows a good eye to be able to capture an interesting shot of a mundane and common scene.</td>', 'I like seeing interesting photos of ordinary subjects. Shows a good eye to be able to capture an interesting shot of a mundane and common scene.', '2009-10-04 16:39:44.000000', NULL, 1),
(5674521, 823327, 83313, '<td valign="top">Strange and different. Slightly quirky. I like it.</td>', 'Strange and different. Slightly quirky. I like it.', '2009-10-04 16:40:44.000000', NULL, 1),
(5674522, 824547, 64446, '<td valign="top">Very nice perspective and the b&amp;w just adds here...</td>', 'Very nice perspective and the b&w just adds here...', '2009-10-04 16:41:36.000000', NULL, 1),
(5674523, 823327, 64446, '<td valign="top">Brilliant image! I that that conveys some mistery without scaring the viewer (maybe because of the shining light). The shadow on the wall is a great touch contrasting the dryness of straight lines...</td>', 'Brilliant image! I that that conveys some mistery without scaring the viewer (maybe because of the shining light). The shadow on the wall is a great touch contrasting the dryness of straight lines...', '2009-10-04 16:41:39.000000', NULL, 1),
(5674524, 824611, 64446, '<td valign="top">Nice take on the challenge. The more I look at this, the more I like it...</td>', 'Nice take on the challenge. The more I look at this, the more I like it...', '2009-10-04 16:41:51.000000', NULL, 1),
(5674525, 824612, 64446, '<td valign="top">Nice perspective and the reflection nuances.</td>', 'Nice perspective and the reflection nuances.', '2009-10-04 16:41:56.000000', NULL, 1),
(5674527, 824591, 64446, '<td valign="top">Unique and unusual subject matter. This one displaying rather interesting patterns. If any improvement, I''d leave out the top black and get more of the floor... Good job! Just now I noticed the reflections in the tiles... bump up!</td>', 'Unique and unusual subject matter. This one displaying rather interesting patterns. If any improvement, I''d leave out the top black and get more of the floor... Good job! Just now I noticed the reflections in the tiles... bump up!', '2009-10-04 16:43:59.000000', NULL, 1),
(5674530, 824499, 83313, '<td valign="top">Needs more pixels, One side should always be at the 640 pixel challenge limit. At this point in the challenge, I am probably the umpteenth one to tell you that. Might have shown off the detail better at a larger image size.</td>', 'Needs more pixels, One side should always be at the 640 pixel challenge limit. At this point in the challenge, I am probably the umpteenth one to tell you that. Might have shown off the detail better at a larger image size.', '2009-10-04 16:45:41.000000', NULL, 1),
(5674533, 824411, 83313, '<td valign="top">Appears to have been taken through a window that gave you some reflections at the top. Not much you can do to fix that in basic editing and would still be some work in advanced.</td>', 'Appears to have been taken through a window that gave you some reflections at the top. Not much you can do to fix that in basic editing and would still be some work in advanced.', '2009-10-04 16:48:05.000000', NULL, 1),
(5674535, 824066, 83313, '<td valign="top">A slightly disorienting view. A little extra pointage for making me pause to examine it more closely.</td>', 'A slightly disorienting view. A little extra pointage for making me pause to examine it more closely.', '2009-10-04 16:49:31.000000', NULL, 1),
(5674537, 824571, 45790, '<td valign="top">While an individual rose can be elegant, and you do meet the challenge by showing the straight rows, a shot or rows of roses is unfortunately boring.</td>', 'While an individual rose can be elegant, and you do meet the challenge by showing the straight rows, a shot or rows of roses is unfortunately boring.', '2009-10-04 16:53:24.000000', NULL, 1),
(5674540, 824549, 45790, '<td valign="top">Idea is fine but this particular fence is dirty, mostly out of focus, and there is too much overexposed area.</td>', 'Idea is fine but this particular fence is dirty, mostly out of focus, and there is too much overexposed area.', '2009-10-04 16:56:20.000000', NULL, 1),
(5674544, 824353, 45790, '<td valign="top">Makes me dizzy! I like howthe ceiling is mostly vanished but I''d have liked not to see the shadow of the shelves against the wall on the left.</td>', 'Makes me dizzy! I like howthe ceiling is mostly vanished but I''d have liked not to see the shadow of the shelves against the wall on the left.', '2009-10-04 17:00:28.000000', NULL, 1),
(5674545, 824611, 45790, '<td valign="top">I''m a sucker for a sunset shot, and the tracks, power poles and wire keep it on challenge.</td>', 'I''m a sucker for a sunset shot, and the tracks, power poles and wire keep it on challenge.', '2009-10-04 17:01:35.000000', NULL, 1),
(5674547, 823468, 83313, '<td valign="top">I like the image itself, however your post processing and saving of it needs a bit more work. The white balance gives a decidedly unattractive cast to this and there is a ton of JPEG compression taking away detail and creating some visible artifacts. I copied it into PaintShop Pro top see, and found I could fix the white balance, but most other adjustments brought out even more pixelated JPEG artifacts.</td>', 'I like the image itself, however your post processing and saving of it needs a bit more work. The white balance gives a decidedly unattractive cast to this and there is a ton of JPEG compression taking away detail and creating some visible artifacts. I copied it into PaintShop Pro top see, and found I could fix the white balance, but most other adjustments brought out even more pixelated JPEG artifacts.', '2009-10-04 17:02:07.000000', NULL, 1),
(5674550, 824708, 83313, '<td valign="top">Nice twist on the topic.</td>', 'Nice twist on the topic.', '2009-10-04 17:03:29.000000', NULL, 1),
(5674552, 823715, 45790, '<td valign="top">You''ve got some glare problems in the upper left. Different angle or time of day (or perhaps a lens hood) would have made a big difference.</td>', 'You''ve got some glare problems in the upper left. Different angle or time of day (or perhaps a lens hood) would have made a big difference.', '2009-10-04 17:04:22.000000', NULL, 1),
(5674555, 823874, 83313, '<td valign="top">Harsh forward facing flash is generally not flattering for any image. Not sure if there is anything I could suggest other than a tripod and and a long exposure in order to avoid the use of the flash.</td>', 'Harsh forward facing flash is generally not flattering for any image. Not sure if there is anything I could suggest other than a tripod and and a long exposure in order to avoid the use of the flash.', '2009-10-04 17:05:38.000000', NULL, 1),
(5674556, 824714, 83313, '<td valign="top">Cool perspective. Seems to have a bit of a bluish cast to it.</td>', 'Cool perspective. Seems to have a bit of a bluish cast to it.', '2009-10-04 17:06:24.000000', NULL, 1),
(5674558, 824588, 83313, '<td valign="top">An interesting semi-abstract shot of an ordinary scene. Good work on this.</td>', 'An interesting semi-abstract shot of an ordinary scene. Good work on this.', '2009-10-04 17:07:17.000000', NULL, 1),
(5674560, 824411, 45790, '<td valign="top">It looked so good in the thumbnail, but full size shows major glare problems.</td>', 'It looked so good in the thumbnail, but full size shows major glare problems.', '2009-10-04 17:07:55.000000', NULL, 1),
(5674563, 824320, 45790, '<td valign="top">I''ve just finished writing two negative comments about glare "ruining" a picture, but in your case it adds. Good job.</td>', 'I''ve just finished writing two negative comments about glare "ruining" a picture, but in your case it adds. Good job.', '2009-10-04 17:10:47.000000', NULL, 1),
(5674591, 824638, 83313, '<td valign="top">I don''t consider it a "good morning" when one wakes up in the middle of the street. On the other hand, that means you didn''t get hit by a car while you slept, and no one took your camera either. I suppose that is a good morning after all.</td>', 'I don''t consider it a "good morning" when one wakes up in the middle of the street. On the other hand, that means you didn''t get hit by a car while you slept, and no one took your camera either. I suppose that is a good morning after all.', '2009-10-04 17:32:16.000000', NULL, 1),
(5674605, 824661, 96227, '<td valign="top">a lot of noise</td>', 'a lot of noise', '2009-10-04 18:12:56.000000', NULL, 1),
(5674644, 824566, 24846, '<td valign="top">Probable Ribbon. Pulls my eye straight to the horizon. Lovely image.</td>', 'Probable Ribbon. Pulls my eye straight to the horizon. Lovely image.', '2009-10-04 18:53:45.000000', NULL, 1),
