(5675186, 824625, 38477, '<td valign="top">I like the idea and the composition, but its too under exposed.</td>', 'I like the idea and the composition, but its too under exposed.', '2009-10-05 03:22:49.000000', NULL, 1),
(5675659, 824547, 110678, '<td valign="top">I really like how it has a sort of 50s feel.</td>', 'I really like how it has a sort of 50s feel.', '2009-10-05 15:09:31.000000', NULL, 1),
